+// Returns true if (n, m) matches "(XorVMask vm2 (MaskAll m1))" used only by an
+// outer XorVMask for mask equality (XNOR).
+static bool is_vector_mask_not_operand_in_xnor_pattern(Node* n, Node* m) {
+  if (n == nullptr || m == nullptr) {
+    return false;
+  }
+
+  if (VectorNode::is_all_ones_vector(m) &&
+      n->Opcode() == Op_XorVMask &&
+      n->outcnt() == 1 &&
+      n->unique_out()->Opcode() == Op_XorVMask) {
+    return true;
+  }
+  return false;
+}
